package com.aicompanion.ai.nav;

import net.minecraft.core.BlockPos;
import net.minecraft.world.phys.Vec3;

/**
 * Concrete physical action generated by the path adapter and executed
 * by CompanionActionExecutor.
 * Separates path planning from physical NPC execution.
 */
public class NavigationAction {
    public enum Type {
        MOVE_TO,
        JUMP,
        BREAK_BLOCK,
        PLACE_BLOCK,
        SWIM,
        WAIT,
        INTERACT
    }

    private final Type type;
    private final BlockPos targetBlock;
    private final Vec3 targetVec;
    private final double speed;
    private final int waitTicks;

    public NavigationAction(Type type, BlockPos targetBlock, Vec3 targetVec, double speed, int waitTicks) {
        this.type = type;
        this.targetBlock = targetBlock;
        this.targetVec = targetVec;
        this.speed = speed;
        this.waitTicks = waitTicks;
    }

    public static NavigationAction moveTo(Vec3 targetVec, double speed) {
        return new NavigationAction(Type.MOVE_TO, null, targetVec, speed, 0);
    }

    public static NavigationAction moveTo(BlockPos blockPos, double speed) {
        return new NavigationAction(Type.MOVE_TO, blockPos, Vec3.atBottomCenterOf(blockPos), speed, 0);
    }

    public static NavigationAction jump(Vec3 forwardVec, double speed) {
        return new NavigationAction(Type.JUMP, null, forwardVec, speed, 0);
    }

    public static NavigationAction breakBlock(BlockPos pos) {
        return new NavigationAction(Type.BREAK_BLOCK, pos, null, 1.0, 0);
    }

    public static NavigationAction placeBlock(BlockPos pos) {
        return new NavigationAction(Type.PLACE_BLOCK, pos, null, 1.0, 0);
    }

    public static NavigationAction swim(Vec3 targetVec, double speed) {
        return new NavigationAction(Type.SWIM, null, targetVec, speed, 0);
    }

    public static NavigationAction waitTicks(int ticks) {
        return new NavigationAction(Type.WAIT, null, null, 0.0, ticks);
    }

    public static NavigationAction interact(BlockPos pos) {
        return new NavigationAction(Type.INTERACT, pos, null, 1.0, 0);
    }

    public Type getType() { return type; }
    public BlockPos getTargetBlock() { return targetBlock; }
    public Vec3 getTargetVec() { return targetVec; }
    public double getSpeed() { return speed; }
    public int getWaitTicks() { return waitTicks; }

    @Override
    public String toString() {
        return type + (targetBlock != null ? " @" + targetBlock.toShortString() : "") +
                (targetVec != null ? " -> " + String.format("(%.1f, %.1f, %.1f)", targetVec.x, targetVec.y, targetVec.z) : "");
    }
}
